/*
* Optionally set $vars.qdrantApiKey for authenticated clusters.
*/

const fetch = require('node-fetch');
const baseUrl = $qdrant_url || $vars.qdrantUrl || 'http://qdrant:6333';
const apiKey = $vars.qdrantApiKey;

const response = await fetch(`${baseUrl.replace(/\/$/, '')}/collections`, {
    method: 'GET',
    headers: apiKey ? { 'api-key': apiKey } : {}
});

if (!response.ok) {
    const text = await response.text();
    throw new Error(`Qdrant error: ${response.status} ${text}`);
}

const data = await response.json();
const names = data.result?.collections?.map((c) => c.name) || [];
return names.length ? names.join(', ') : 'No collections found.';
